head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면이 최초 로드될때 실행되는 초기화 이벤트 — 화면 초기화(init)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00312.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_RelcomMutlTrd_oncelldblclick
 * @description 팝업호출
 * @param {Number} rowIndex 더블클릭한 행 인덱스
 * @param {Number} columnIndex 더블클릭한 컬럼 인덱스
 * @param {String} columnId 더블클릭한 컬럼 아이디
 * @returns {void}
 * @hidden N
 * @example scwin.grd_RelcomMutlTrd_oncelldblclick(0, 0, "basYymm");
 */
scwin.grd_RelcomMutlTrd_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        if (columnId === "basYymm") {
            // 담보및보증내역 상세  팝업 오픈
            scwin.relcomMutlTrdDtlSrchOpen(rowIndex);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00312.grd_RelcomMutlTrd_oncelldblclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 * @example scwin.init();
 */
scwin.init = function() {
    scwin.search();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dlt_RelcomMutlTrdRes.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Boolean} 조회조건이 유효하면 true
 * @hidden N
 * @example if (!scwin.chkValid()) { return; }
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd = $p.parent().wfm_header.getWindow().scwin.fn_GetKisCd();
    if (scwin.vKisCd === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 담보및지급보증 조회
 * @returns {void}
 * @hidden N
 * @example scwin.search();
 */
scwin.search = function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }
    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();

    const url = "/api/listing/nice/individual-notes/" + ibxKisCd + "/collateral-guarantees";
    $c.sbm.setAction(sbm_dlt_RetiPayAlwnc, url);
    $c.sbm.execute(sbm_dlt_RetiPayAlwnc);
};

/**
 * @method
 * @name relcomMutlTrdDtlSrchOpen
 * @description 담보및지급보증 상세 팝업
 * @param {Number} pRow 선택 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.relcomMutlTrdDtlSrchOpen(0);
 */
scwin.relcomMutlTrdDtlSrchOpen = function(pRow) {

    const url = "/ui/lst/fis/ULDFIS00300_P7.xml";
    const popTitle = "담보및 보증내역 검색";

    const opts = {
        id: "ULDFIS00300_P7",
        popupName: popTitle,
        width: 920,
        height: 880,
        frameModal: "top",
    };
    const popData = dlt_RelcomMutlTrdRes.getRowJSON(pRow);
    $c.win.openPopup(url, opts, popData);
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 * @example scwin.excelDownload();
 */
scwin.excelDownload = function() {
    if (dlt_RelcomMutlTrdRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_RelcomMutlTrd, {fileName: "담보및지급보증 조회", type: "8"});
};

/**
 * @method
 * @name gform_onload
 * @description gform 로드 이벤트(레거시 호환) — 화면 초기화(init)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = function() {
    scwin.init();
};
